// ----------------------------------------------------------
// NYC Bus Infrastructure Map
// Static data generated by GitHub Actions
// ----------------------------------------------------------

// ----------------------------------------------------------
// Map Initialization
// ----------------------------------------------------------

const map = L.map("map", {
  preferCanvas: true
}).setView([40.71, -74.00], 12);

L.tileLayer(
  "https://{s}.basemaps.cartocdn.com/light_all/{z}/{x}/{y}{r}.png",
  {
    attribution: "© OpenStreetMap contributors © CARTO",
    maxZoom: 19
  }
).addTo(map);

proj4.defs(
  "EPSG:2260",
  "+proj=lcc +lat_1=40.66666666666666 +lat_2=41.03333333333333 " +
  "+lat_0=40.16666666666666 +lon_0=-74 +x_0=984250 +y_0=0 " +
  "+datum=NAD83 +units=us-ft +no_defs"
);

// ----------------------------------------------------------
// Layers
// ----------------------------------------------------------

const busStopsLayer = L.layerGroup();
const busRoutesLayer = L.layerGroup();
const busSignsLayer = L.layerGroup();
const busLanesLayer = L.layerGroup();



// List GTFS feed folders manually (add more as needed)
const GTFS_FEEDS = [
  "gtfs_bx",
  "gtfs_q",
  "gtfs_m",
  "gtfs_si",
  "gtfs_b",
  "gtfs_busco"
];


const routeColorCache = {};

function randomRouteColor(routeId) {
  // If already assigned, return it
  if (routeColorCache[routeId]) return routeColorCache[routeId];

  // Generate a random but visually pleasant color
  const hue = Math.floor(Math.random() * 360);
  const color = `hsl(${hue}, 70%, 45%)`;

  routeColorCache[routeId] = color;
  return color;
}

busStopsLayer.addTo(map);
busRoutesLayer.addTo(map);
busSignsLayer.addTo(map);
busLanesLayer.addTo(map);

L.control.layers(
  null,
  {
    "Bus Stops": busStopsLayer,
    "Bus Routes": busRoutesLayer,
    "Bus Signs": busSignsLayer,
    "Bus Lanes": busLanesLayer
  },
  {
    collapsed: false
  }
).addTo(map);

// ----------------------------------------------------------
// Utilities
// ----------------------------------------------------------


async function fetchJSON(url) {
  const resp = await fetch(url, {
    cache: "no-store"
  });

  if (!resp.ok) {
    throw new Error(`${url}: ${resp.status}`);
  }

  return resp.json();
}

async function loadRoutesForFeed(feed) {
  const text = await fetchText(`feeds/${feed}/routes.txt`);
  const rows = parseCSV(text);

  const map = {};
  rows.forEach(r => {
    map[r.route_id] = {
      short: r.route_short_name || r.route_long_name || r.route_id,
      color: r.route_color ? `#${r.route_color}` : null,
      textColor: r.route_text_color ? `#${r.route_text_color}` : "#000000"
    };
  });

  return map;
}

function safeNumber(value) {
  const n = Number(value);
  return Number.isFinite(n) ? n : null;
}

function fitToInfrastructure() {
  const groups = [
    busRoutesLayer,
    busStopsLayer,
    busLanesLayer
  ];

  let bounds = null;

  groups.forEach(layer => {
    if (
      layer.getLayers &&
      layer.getLayers().length > 0 &&
      layer.getBounds
    ) {
      const b = layer.getBounds();

      if (b.isValid()) {
        bounds = bounds ? bounds.extend(b) : b;
      }
    }
  });

  if (bounds?.isValid()) {
    map.fitBounds(bounds, {
      padding: [20, 20]
    });
  }
}

// ----------------------------------------------------------
// Coordinate Conversion
// ----------------------------------------------------------


function epsg2260ToWGS84(x_ft, y_ft) {
  // proj4 returns [lon, lat]
  const [lon, lat] = proj4("EPSG:2260", "WGS84", [x_ft, y_ft]);
  return [lat, lon];
}

// ----------------------------------------------------------
// Cached GTFS Data
// ----------------------------------------------------------
async function fetchText(url) {
  const resp = await fetch(url, { cache: "no-store" });
  if (!resp.ok) throw new Error(`${url}: ${resp.status}`);
  return resp.text();
}

function parseCSV(text) {
  const lines = text.split(/\r?\n/).filter(l => l.trim() !== "");
  const headers = lines[0].split(",");
  return lines.slice(1).map(line => {
    const cols = line.split(",");
    const obj = {};
    headers.forEach((h, i) => {
      obj[h] = cols[i];
    });
    return obj;
  });
}

async function loadGTFSFeeds() {
  for (const feed of GTFS_FEEDS) {
    try {
      console.log(`Loading GTFS feed: ${feed}`);

      const [shapesTxt, stopsTxt, routesMap] = await Promise.all([
        fetchText(`feeds/${feed}/shapes.txt`),
        fetchText(`feeds/${feed}/stops.txt`),
        loadRoutesForFeed(feed)
      ]);

      const shapes = parseCSV(shapesTxt);
      const stops = parseCSV(stopsTxt);

      drawStops(stops);
      drawShapesFromGTFS(shapes, routesMap);

      console.log(`Loaded ${feed}`);
    } catch (err) {
      console.warn(`GTFS feed ${feed} failed:`, err);
    }
  }
}

function drawShapesFromGTFS(shapes, routesMap, shapeRouteMap) {
  const grouped = {};

  shapes.forEach(row => {
    const shapeId = row.shape_id;
    if (!grouped[shapeId]) grouped[shapeId] = [];
    grouped[shapeId].push({
      lat: Number(row.shape_pt_lat),
      lon: Number(row.shape_pt_lon),
      seq: Number(row.shape_pt_sequence)
    });
  });

  Object.keys(grouped).forEach(shapeId => {
    const pts = grouped[shapeId]
      .sort((a, b) => a.seq - b.seq)
      .map(p => [p.lat, p.lon]);

    if (pts.length < 2) return;

    // route_id from shapeRouteMap (from trips.txt)
    const route_id = shapeRouteMap[shapeId] || shapeId;

    // route short name from routes.txt (optional)
    const shortName = routesMap[route_id]?.short || route_id;

    // 🎨 Random color per route
    const color = randomRouteColor(route_id);

    L.polyline(pts, {
      color,
      weight: 3,
      opacity: 0.85
    })
      .bindTooltip(shortName, {
        sticky: true,
        direction: "auto"
      })
      .addTo(busRoutesLayer);
  });
}

async function loadCachedGTFS() {
  try {
    const [stops, shapes] = await Promise.all([
      fetchJSON("data/stops.json"),
      fetchJSON("data/shapes.json")
    ]);

    drawStops(stops);
    drawShapes(shapes);

    console.log(
      `Loaded ${stops.length} stops and ${shapes.length} shapes`
    );
  } catch (err) {
    console.error("GTFS cache load failed:", err);
  }
}

// ----------------------------------------------------------
// Stops
// ----------------------------------------------------------

function drawStops(stops) {
  stops.forEach(stop => {
    const lat = safeNumber(stop.lat);
    const lon = safeNumber(stop.lon);

    if (lat === null || lon === null) return;

    // Use a light blue for bus stop markers
    L.circleMarker([lat, lon], {
      radius: 3,
      color: "#66CCFF",
      fillColor: "#66CCFF",
      fillOpacity: 0.7,
      weight: 1
    })
      .bindTooltip(stop.stop_name || stop.stop_id || "")
      .addTo(busStopsLayer);
  });
}

// ----------------------------------------------------------
// Route Shapes
// ----------------------------------------------------------

function drawShapes(shapes) {
  shapes.forEach(shape => {
    if (!Array.isArray(shape.points)) return;

    const pts = shape.points
      .map(p => {
        if (Array.isArray(p)) {
          return [Number(p[0]), Number(p[1])];
        }

        return [
          Number(p.lat),
          Number(p.lon)
        ];
      })
      .filter(
        p =>
          Number.isFinite(p[0]) &&
          Number.isFinite(p[1])
      );

    if (pts.length < 2) return;

    L.polyline(pts, {
      color: "#6f42c1",
      weight: 2,
      opacity: 0.6
    })
      .bindTooltip(shape.route_id || "")
      .addTo(busRoutesLayer);
  });
}

function routeColor(routeShortName) {
  // deterministic color seed
  const hash = [...routeShortName].reduce((a, c) => a + c.charCodeAt(0), 0);
  const hue = hash % 360;

  return `hsl(${hue}, 70%, 45%)`;
}
